/** Invoice name → «Add name» → имя счёта. */
export async function setInvoiceName(page: Page, title: string) {
  await page.getByText('Add name', { exact: true }).click();
  const input = page.getByRole('textbox', { name: /name/i }).or(page.getByPlaceholder(/name/i)).first();
  await input.fill(title);
  await input.press('Enter');
  await expect(page.getByText(title)).toBeVisible();
}

/** Jobs → первая работа → вкладка Items. Возвращает номер работы. */
export async function openFirstJobItems(page: Page): Promise<string> {
  await page.goto(pp('/jobs'));
  const cell = page.getByRole('cell', { name: /^JOB-\d+$/ }).first();
  const jobNo = (await cell.innerText()).trim();
  await cell.click();
  await page.waitForURL(/\/JobDetail\?id=/);
  const url = new URL(page.url());
  url.searchParams.set('tab', 'items');
  await page.goto(url.toString());
  await expect(page.getByRole('button', { name: 'Add Item' }).first()).toBeVisible();
  return jobNo;
}

/** Строка таблицы с текстом. */
export const itemRow = (page: Page, name: string) => page.getByRole('row').filter({ hasText: name });

/** Очистка (не роняет тест): удалить строку позиции в текущем документе (иконка корзины / Delete в строке). */
export async function removeItemRow(page: Page, name: string) {
  if (page.isClosed()) return;
  try {
    const row = itemRow(page, name).first();
    if (!(await row.count())) return;
    await row.hover();
    await row.getByRole('button', { name: /delete|remove|trash/i }).or(row.getByRole('button').last()).first().click();
    const confirm = page.getByRole('alertdialog').or(page.getByRole('dialog')).getByRole('button', { name: /^(Delete|Remove|Confirm|Yes)/i });
    if (await confirm.count()) await confirm.first().click();
    await expect(itemRow(page, name)).toHaveCount(0, { timeout: 10_000 });
  } catch (e) {
    console.warn(`очистка позиции «${name}» не удалась — удалить вручную: ${String(e).slice(0, 200)}`);
  }
}

/**
 * Очистка (не роняет тест): в списке (/assessments или /invoices) все строки с текстом → Actions → Delete (или Archive).
 */
export async function removeFromList(page: Page, listPath: '/assessments' | '/invoices', text: string) {
  if (page.isClosed()) return;
  try {
    await page.goto(pp(listPath));
    const search = page.getByPlaceholder(/search/i).first();
    if (await search.count()) await search.fill(text);
    const rows = page.getByRole('row').filter({ hasText: text });
    const n = await rows.count();
    for (let i = 0; i < n; i++) {
      await rows.first().getByRole('button', { name: /Actions/ }).or(rows.first().getByRole('button').last()).first().click();
      const del = page.getByRole('menuitem', { name: /Delete/i });
      if (await del.count()) {
        await del.first().click();
        const confirm = page.getByRole('alertdialog').or(page.getByRole('dialog')).getByRole('button', { name: /^(Delete|Confirm|Yes)/i });
        if (await confirm.count()) await confirm.first().click();
      } else {
        await page.getByRole('menuitem', { name: /Archive/i }).first().click();
      }
      await expect(rows).toHaveCount(n - i - 1, { timeout: 10_000 });
    }
  } catch (e) {
    console.warn(`очистка «${text}» в ${listPath} не удалась — удалить вручную: ${String(e).slice(0, 200)}`);
  }
}

/** Очистка (не роняет тест): открыть документ по адресу → Actions → Delete → подтвердить. */
export async function removeDocumentAt(page: Page, url: string | null, label: string) {
  if (page.isClosed() || !url) return;
  try {
    await page.goto(url);
    await page.getByRole('button', { name: 'Actions' }).filter({ visible: true }).first().click();
    await page.getByRole('menuitem', { name: /Delete/i }).first().click();
    const confirm = page.getByRole('alertdialog').or(page.getByRole('dialog')).getByRole('button', { name: /^(Delete|Confirm|Yes)/i });
    if (await confirm.count()) await confirm.first().click();
    await expect(page).not.toHaveURL(url, { timeout: 10_000 });
  } catch (e) {
    console.warn(`очистка «${label}» (${url}) не удалась — удалить вручную: ${String(e).slice(0, 200)}`);
  }
}
